        { title: "Aama Yojna and Bahini Scheme", publisher: "TNPSC Thervu Pettagam", url: "https://www.tnpscthervupettagam.com/currentaffairs-detail/aama-yojna-and-bahini-scheme/chief", year: 2022 },
        { title: "Sikkim Legislative Assembly passes budget grants for multiple sectors", publisher: "Northeast Today", url: "https://northeasttoday.in/northeast/sikkim-legislative-assembly-passes-budget-grants-for-multiple-sectors/", year: 2025 }
